insert into public.score_levels (value, label, description) values
  (1, 'Weak', 'Missing, incorrect, non-functional, or little/no meaningful evidence.'),
  (2, 'Developing', 'Partially demonstrated; important gaps remain or substantial support is needed.'),
  (3, 'Meets Expectations', 'Core requirement is present, understandable, and works at an acceptable/basic level.'),
  (4, 'Strong', 'Complete, accurate, well integrated, and supported by good evidence; only minor issues.'),
  (5, 'Excellent', 'Highly effective, reliable, purposeful, well-tested/polished, and clearly justified by the team.')
insert into public.rubric_templates (id, title, subtitle, source_pdf, scale_instruction, guidance, core_max, bonus_max) values
  ('DEMI_G4', 'Stage 3 Judges'' Rubric - DEMI Grade 4', 'App Lab Project - Stage 3 Judge Evaluation', 'DEMI_Grade_4_Judges_Rubric_Revised.pdf', 'Enter ONE number from 1 to 5. Every row is worth 5 points; harder sections have more rows and therefore more weight.', 'Judge the final Stage 3 work, using the previous-phase requirements as the baseline. Reward evidence, correct integration, and purposeful design - not complexity for its own sake. Testing: look for real trials/results, not only claims. Hardware: reward the best-fit use of components and reliable integration. Teamwork & presentation: look for shared ownership, clear communication, and the ability of multiple members to answer questions.', 100, 10)
