  ('DEMI_G4.S1', 'DEMI_G4', 1, 'Problem, Research & Solution', 20, false),
  ('DEMI_G4.S2', 'DEMI_G4', 2, 'UX & Prototype Design', 15, false),
  ('DEMI_G4.S3', 'DEMI_G4', 3, 'Programming & Functionality', 25, false),
  ('DEMI_G4.S4', 'DEMI_G4', 4, 'Testing & Improvement', 15, false),
  ('DEMI_G4.S5', 'DEMI_G4', 5, 'Business & Value', 10, false),
  ('DEMI_G4.S6', 'DEMI_G4', 6, 'Teamwork & Presentation', 15, false),
  ('DEMI_G4.BONUS', 'DEMI_G4', 7, 'Extra Requirements / Optional Bonus', 10, true)
insert into public.rubric_criteria (id, section_id, template_id, is_bonus, position, title, description, max_points) values
  ('DEMI_G4.S1.C1', 'DEMI_G4.S1', 'DEMI_G4', false, 1, 'Problem & target user', 'The team clearly defines the real-world problem, who is affected, and why it matters.', 5),
  ('DEMI_G4.S1.C2', 'DEMI_G4.S1', 'DEMI_G4', false, 2, 'Research on similar solutions', 'Shows credible examples/screenshots of 1-2 similar apps or solutions and explains what was learned.', 5),
  ('DEMI_G4.S1.C3', 'DEMI_G4.S1', 'DEMI_G4', false, 3, 'Research insight / gap', 'Explains what is missing or could be improved in existing solutions and connects that insight to the project.', 5),
  ('DEMI_G4.S1.C4', 'DEMI_G4.S1', 'DEMI_G4', false, 4, 'App solution & main features', 'The app purpose and 2-3 main features directly address the identified problem and user needs.', 5),
  ('DEMI_G4.S2.C1', 'DEMI_G4.S2', 'DEMI_G4', false, 1, 'User flow', 'Screen-to-screen journey is logical, complete, and easy to follow.', 5),
  ('DEMI_G4.S2.C2', 'DEMI_G4.S2', 'DEMI_G4', false, 2, 'Wireframes / screen design', 'Screens or mockups match the planned features and show a clear interface structure.', 5),
  ('DEMI_G4.S2.C3', 'DEMI_G4.S2', 'DEMI_G4', false, 3, 'Usability & design consistency', 'Buttons, labels, navigation, layout, and visual choices are understandable and consistent for the target user.', 5),
  ('DEMI_G4.S3.C1', 'DEMI_G4.S3', 'DEMI_G4', false, 1, 'Working prototype', 'Core app screens and planned features function during the demonstration.', 5),
  ('DEMI_G4.S3.C2', 'DEMI_G4.S3', 'DEMI_G4', false, 2, 'Events & user input', 'Events such as button clicks trigger the correct actions and user inputs are handled properly.', 5),
  ('DEMI_G4.S3.C3', 'DEMI_G4.S3', 'DEMI_G4', false, 3, 'Variables & conditions', 'Variables and conditional logic are used correctly to control app behavior.', 5),
  ('DEMI_G4.S3.C4', 'DEMI_G4.S3', 'DEMI_G4', false, 4, 'Loops / functions / data logic', 'Uses suitable loops, functions, lists, or reusable logic where needed; logic is organized rather than repeated unnecessarily.', 5),
  ('DEMI_G4.S3.C5', 'DEMI_G4.S3', 'DEMI_G4', false, 5, 'Reliability & correctness', 'App produces correct results, handles common mistakes reasonably, and does not break during normal use.', 5),
  ('DEMI_G4.S4.C1', 'DEMI_G4.S4', 'DEMI_G4', false, 1, 'Testing coverage', 'Team tests important screens, buttons, inputs, and user journeys instead of only one happy path.', 5),
  ('DEMI_G4.S4.C2', 'DEMI_G4.S4', 'DEMI_G4', false, 2, 'Evidence of testing', 'Shows concrete evidence such as test notes, screenshots, user feedback, before/after examples, or repeated trials.', 5),
  ('DEMI_G4.S4.C3', 'DEMI_G4.S4', 'DEMI_G4', false, 3, 'Improvement from findings', 'Team identifies issues found during testing and explains or demonstrates meaningful improvements.', 5),
  ('DEMI_G4.S5.C1', 'DEMI_G4.S5', 'DEMI_G4', false, 1, 'User value & delivery idea', 'Explains who benefits, what value the app provides, and a realistic way it could be offered or shared.', 5),
  ('DEMI_G4.S5.C2', 'DEMI_G4.S5', 'DEMI_G4', false, 2, 'Differentiation & feasibility', 'Explains why the solution is useful compared with alternatives and keeps the idea realistic for the intended users.', 5),
  ('DEMI_G4.S6.C1', 'DEMI_G4.S6', 'DEMI_G4', false, 1, 'Shared teamwork & roles', 'Participation is balanced; team members contribute and can explain their own role in the project.', 5),
  ('DEMI_G4.S6.C2', 'DEMI_G4.S6', 'DEMI_G4', false, 2, 'Clear communication & demo', 'Presentation is organized, understandable, within time, and the demo supports the story of the project.', 5),
  ('DEMI_G4.S6.C3', 'DEMI_G4.S6', 'DEMI_G4', false, 3, 'Questions & project understanding', 'Team members answer judge questions clearly and show shared understanding of the app, decisions, and testing.', 5),
  ('DEMI_G4.BONUS.C1', 'DEMI_G4.BONUS', 'DEMI_G4', true, 1, 'Advanced app feature - usefulness & depth', 'Optional extra feature meaningfully strengthens the same app rather than adding an unrelated idea.', 5),
  ('DEMI_G4.BONUS.C2', 'DEMI_G4.BONUS', 'DEMI_G4', true, 2, 'Advanced app feature - working evidence', 'Shows screenshots/code or a working demonstration proving the advanced feature is implemented or credibly prototyped.', 5)
