insert into public.rubric_criteria (id, section_id, template_id, is_bonus, position, title, description, max_points) values
  ('DEMI_G5.S1.C1', 'DEMI_G5.S1', 'DEMI_G5', false, 1, 'Problem, target user & research', 'Clearly explains the problem, user, importance, and supporting research about similar ideas or needs.', 5),
  ('DEMI_G5.S1.C2', 'DEMI_G5.S1', 'DEMI_G5', false, 2, 'Solution alignment', 'The proposed solution and its functions directly address the researched problem.', 5),
  ('DEMI_G5.S1.C3', 'DEMI_G5.S1', 'DEMI_G5', false, 3, 'User value', 'The team can explain how the final system helps the target user and why the solution is worthwhile.', 5),
  ('DEMI_G5.S2.C1', 'DEMI_G5.S2', 'DEMI_G5', false, 1, 'Purposeful kit/component choice', 'Hardware is selected because it fits the solution; unnecessary components are avoided and each chosen part has a clear role.', 5),
  ('DEMI_G5.S2.C2', 'DEMI_G5.S2', 'DEMI_G5', false, 2, 'Input/output component use', 'Sensors and outputs/actuators are used correctly and their roles match the Stage 2 hardware plan.', 5),
