  ('DEMI_G5.S2.C4', 'DEMI_G5.S2', 'DEMI_G5', false, 4, 'System integration', 'Input -> Arduino/controller -> output behavior works as one coherent system and matches the block/circuit design.', 5),
  ('DEMI_G5.S2.C5', 'DEMI_G5.S2', 'DEMI_G5', false, 5, 'Best use of hardware & reliability', 'Hardware capabilities are used effectively for the problem, and the physical setup performs consistently during repeated demonstrations.', 5),
  ('DEMI_G5.S3.C1', 'DEMI_G5.S3', 'DEMI_G5', false, 1, 'Programming logic', 'Events/inputs, variables, conditions, loops, and outputs work together correctly.', 5),
  ('DEMI_G5.S3.C2', 'DEMI_G5.S3', 'DEMI_G5', false, 2, 'Code organization', 'Functions or reusable blocks are used appropriately; code is readable and avoids unnecessary repetition.', 5),
  ('DEMI_G5.S3.C3', 'DEMI_G5.S3', 'DEMI_G5', false, 3, 'AI/ML feature relevance', 'AI feature supports the same problem and is more than a disconnected add-on.', 5),
  ('DEMI_G5.S3.C4', 'DEMI_G5.S3', 'DEMI_G5', false, 4, 'AI evidence & integration', 'Team shows model/concept evidence and clearly explains how AI input/output connects to the overall solution.', 5),
  ('DEMI_G5.S4.C1', 'DEMI_G5.S4', 'DEMI_G5', false, 1, 'Prototype completeness', 'The physical/digital prototype demonstrates the main planned behavior end-to-end.', 5),
  ('DEMI_G5.S4.C2', 'DEMI_G5.S4', 'DEMI_G5', false, 2, 'Evidence of testing', 'Shows repeated tests, observations, measurements, screenshots, logs, or other evidence rather than only stating that testing happened.', 5),
  ('DEMI_G5.S4.C3', 'DEMI_G5.S4', 'DEMI_G5', false, 3, 'Improvement & reliability', 'Team uses test findings to improve timing, thresholds, interaction, accuracy, or reliability and can explain the change.', 5),
  ('DEMI_G5.S5.C1', 'DEMI_G5.S5', 'DEMI_G5', false, 1, 'Customer & value proposition', 'Target customer/user matches the original problem and the value is clear.', 5),
  ('DEMI_G5.S5.C2', 'DEMI_G5.S5', 'DEMI_G5', false, 2, 'Practical delivery / feasibility', 'Explains a realistic way the solution could be offered, used, or adopted.', 5),
  ('DEMI_G5.S6.C1', 'DEMI_G5.S6', 'DEMI_G5', false, 1, 'Shared teamwork & contribution', 'Roles are balanced and all members visibly contribute to building, testing, or explaining the project.', 5),
  ('DEMI_G5.S6.C2', 'DEMI_G5.S6', 'DEMI_G5', false, 2, 'Technical communication', 'Team explains hardware, code, AI, and design decisions in language appropriate to judges.', 5),
  ('DEMI_G5.S6.C3', 'DEMI_G5.S6', 'DEMI_G5', false, 3, 'Presentation, demo & Q&A', 'Presentation is clear and well paced; demo evidence is convincing; answers show shared understanding.', 5),
  ('DEMI_G5.BONUS.C1', 'DEMI_G5.BONUS', 'DEMI_G5', true, 1, 'Advanced programming feature', 'Optional stronger programming feature (functions, lists, nested logic, etc.) is useful and supported by code/logic evidence.', 5),
  ('DEMI_G5.BONUS.C2', 'DEMI_G5.BONUS', 'DEMI_G5', true, 2, 'Advanced AI feature', 'Optional AI feature goes beyond the basic AI requirement and is supported by a model, screenshot, result, or credible prototype evidence.', 5)
