  ('DECI_L3.S1', 'DECI_L3', 1, 'Problem, Research & Solution', 15, false),
  ('DECI_L3.S2', 'DECI_L3', 2, 'System, Hardware, IoT & Circuit', 25, false),
  ('DECI_L3.S3', 'DECI_L3', 3, 'Programming & AI / Data', 20, false),
  ('DECI_L3.S4', 'DECI_L3', 4, 'Digital Identity & Track Integration', 10, false),
  ('DECI_L3.S5', 'DECI_L3', 5, 'Testing & Validation', 10, false),
  ('DECI_L3.S6', 'DECI_L3', 6, 'Business & Value', 5, false),
  ('DECI_L3.S7', 'DECI_L3', 7, 'Teamwork & Presentation', 15, false),
  ('DECI_L3.BONUS', 'DECI_L3', 8, 'Extra Requirements / Optional Bonus', 10, true)
insert into public.rubric_criteria (id, section_id, template_id, is_bonus, position, title, description, max_points) values
  ('DECI_L3.S1.C1', 'DECI_L3.S1', 'DECI_L3', false, 1, 'Problem, user & research', 'Clearly defines the problem/user and supports it with relevant research findings and references.', 5),
  ('DECI_L3.S1.C2', 'DECI_L3.S1', 'DECI_L3', false, 2, 'Solution & user interaction', 'Solution directly addresses the problem and explains a complete user interaction.', 5),
  ('DECI_L3.S1.C3', 'DECI_L3.S1', 'DECI_L3', false, 3, 'Features & value', 'Main functions are coherent, useful, and consistent with the same target user.', 5),
  ('DECI_L3.S2.C1', 'DECI_L3.S2', 'DECI_L3', false, 1, 'ESP32 system architecture', 'System clearly explains sensor/input -> ESP32 processing -> decision -> output/communication, including relevant ESP32 capabilities.', 5),
  ('DECI_L3.S2.C2', 'DECI_L3.S2', 'DECI_L3', false, 2, 'Purposeful platform & component choice', 'Kit/platform, ESP32/ESP32 Camera, sensors, and actuators are selected because they fit the project.', 5),
  ('DECI_L3.S2.C3', 'DECI_L3.S2', 'DECI_L3', false, 3, 'IoT communication', 'Wi-Fi/Bluetooth/data flow is technically sensible, including two-way communication where needed.', 5),
  ('DECI_L3.S2.C4', 'DECI_L3.S2', 'DECI_L3', false, 4, 'Circuit correctness', 'Circuit connections and selected GPIO/input types are reasonable and match the implemented plan.', 5),
  ('DECI_L3.S2.C5', 'DECI_L3.S2', 'DECI_L3', false, 5, 'Best hardware use & reliability', 'Hardware/ESP32 capabilities are used effectively and operate consistently under repeated demonstrations.', 5),
  ('DECI_L3.S3.C1', 'DECI_L3.S3', 'DECI_L3', false, 1, 'Programming/control logic', 'Inputs, decisions, timing/loops, outputs, and communication are implemented logically and reliably.', 5),
  ('DECI_L3.S3.C2', 'DECI_L3.S3', 'DECI_L3', false, 2, 'Data collection & decisions', 'Collected sensor/image data is relevant and is used appropriately to drive decisions or actions.', 5),
  ('DECI_L3.S3.C3', 'DECI_L3.S3', 'DECI_L3', false, 3, 'AI approach & relevance', 'If AI/computer vision is used, classification/object detection or other approach fits the problem and data.', 5),
  ('DECI_L3.S3.C4', 'DECI_L3.S3', 'DECI_L3', false, 4, 'Evidence of AI/data flow', 'Shows model/data-flow/visual evidence and explains how results connect back to the system.', 5),
  ('DECI_L3.S4.C1', 'DECI_L3.S4', 'DECI_L3', false, 1, 'Digital identity', 'Project name, logo, palette, and visual style are consistent and fit the product/user.', 5),
  ('DECI_L3.S4.C2', 'DECI_L3.S4', 'DECI_L3', false, 2, 'Applied track integration', 'Relevant team track output (Web, UI/UX, Data Science, Cybersecurity) is clearly connected to the same ESP32 project and shows real evidence.', 5),
  ('DECI_L3.S5.C1', 'DECI_L3.S5', 'DECI_L3', false, 1, 'Testing evidence & success checks', 'Shows repeated functional tests or data/communication tests with observable success criteria.', 5),
  ('DECI_L3.S5.C2', 'DECI_L3.S5', 'DECI_L3', false, 2, 'Improvement & system reliability', 'Team identifies weaknesses and improves hardware, logic, data, interface, or communication based on evidence.', 5),
  ('DECI_L3.S6.C1', 'DECI_L3.S6', 'DECI_L3', false, 1, 'Customer, value & pricing', 'Target customer, value proposition, and basic pricing/delivery idea are clear and realistic.', 5),
  ('DECI_L3.S7.C1', 'DECI_L3.S7', 'DECI_L3', false, 1, 'Cross-track teamwork', 'Members integrate their track contributions into one solution instead of presenting disconnected pieces.', 5),
  ('DECI_L3.S7.C2', 'DECI_L3.S7', 'DECI_L3', false, 2, 'Communication & technical ownership', 'Different members can explain decisions and demonstrate understanding beyond only their own slide/part.', 5),
  ('DECI_L3.S7.C3', 'DECI_L3.S7', 'DECI_L3', false, 3, 'Presentation, demo & Q&A', 'Project story is clear and professional; evidence is well selected; team handles judge questions effectively.', 5),
  ('DECI_L3.BONUS.C1', 'DECI_L3.BONUS', 'DECI_L3', true, 1, 'Advanced AI feature', 'Optional advanced AI/ML feature goes beyond the core data plan and includes prototype/evidence.', 5),
  ('DECI_L3.BONUS.C2', 'DECI_L3.BONUS', 'DECI_L3', true, 2, 'Advanced system feature', 'Optional stronger IoT, cybersecurity, data processing, or digital experience feature improves the same system and includes evidence.', 5)
insert into public.rubric_templates (id, title, subtitle, source_pdf, scale_instruction, guidance, core_max, bonus_max) values
  ('DECI_L45', 'Stage 3 Judges'' Rubric - DECI Levels 4 & 5', 'Combined Advanced Project - Stage 3 Judge Evaluation', 'DECI_Levels_4_5_Judges_Rubric_Revised.pdf', 'Enter ONE number from 1 to 5. Every row is worth 5 points; harder sections have more rows and therefore more weight.', 'Judge the final Stage 3 work, using the previous-phase requirements as the baseline. Reward evidence, correct integration, and purposeful design - not complexity for its own sake. Testing: look for real trials/results, not only claims. Hardware: reward the best-fit use of components and reliable integration. Teamwork & presentation: look for shared ownership, clear communication, and the ability of multiple members to answer questions.', 100, 15)
insert into public.rubric_sections (id, template_id, position, title, weight, is_bonus) values
  ('DECI_L45.S1', 'DECI_L45', 1, 'Problem Analysis & Complete Solution', 10, false),
  ('DECI_L45.S2', 'DECI_L45', 2, 'Architecture, Hardware & Embedded IoT', 25, false),
  ('DECI_L45.S3', 'DECI_L45', 3, 'AI, Data Processing & Data Science', 20, false),
  ('DECI_L45.S4', 'DECI_L45', 4, 'Product, UX, Web & Cybersecurity', 15, false),
  ('DECI_L45.S5', 'DECI_L45', 5, 'Business, Testing & Improvement', 15, false),
  ('DECI_L45.S6', 'DECI_L45', 6, 'Teamwork & Presentation', 15, false),
  ('DECI_L45.BONUS', 'DECI_L45', 7, 'Extra Requirements / Optional Bonus', 15, true)
insert into public.rubric_criteria (id, section_id, template_id, is_bonus, position, title, description, max_points) values
  ('DECI_L45.S1.C1', 'DECI_L45.S1', 'DECI_L45', false, 1, 'Problem, research & opportunity', 'Defines the real problem, target users, existing alternatives, supporting research, and the specific value/opportunity for the solution.', 5),
  ('DECI_L45.S1.C2', 'DECI_L45.S1', 'DECI_L45', false, 2, 'Complete end-to-end solution', 'User journey and system behavior form a complete flow from data capture/input through processing, user action, and feedback/logging where appropriate.', 5),
  ('DECI_L45.S2.C1', 'DECI_L45.S2', 'DECI_L45', false, 1, 'System architecture & data flow', 'Hardware, ESP32/ESP32 Camera, communication, AI/software processing, and user interface are connected in a technically coherent architecture.', 5),
  ('DECI_L45.S2.C2', 'DECI_L45.S2', 'DECI_L45', false, 2, 'Purposeful hardware selection', 'Physical platform, sensors/actuators, ESP32, and ESP32 Camera roles are justified by the problem; components are not added without purpose.', 5),
  ('DECI_L45.S2.C3', 'DECI_L45.S2', 'DECI_L45', false, 3, 'Circuit & embedded logic', 'Circuit, input processing, states/events, actuator responses, and control logic are technically sound and match the implementation.', 5),
  ('DECI_L45.S2.C4', 'DECI_L45.S2', 'DECI_L45', false, 4, 'IoT / communication integration', 'Data transmission, cloud/local processing, and device-to-system communication are reliable and appropriate for the use case.', 5),
  ('DECI_L45.S2.C5', 'DECI_L45.S2', 'DECI_L45', false, 5, 'Best hardware use, reliability & scalability', 'Hardware capabilities are used efficiently; system performs consistently and design choices consider reliability and practical scaling.', 5),
  ('DECI_L45.S3.C1', 'DECI_L45.S3', 'DECI_L45', false, 1, 'Data pipeline', 'Data collection, preparation, processing, and decision flow are clear and technically appropriate.', 5),
  ('DECI_L45.S3.C2', 'DECI_L45.S3', 'DECI_L45', false, 2, 'AI/ML approach & performance evidence', 'Chosen AI/ML method fits the task; team shows relevant outputs, confidence/accuracy evidence, or justified evaluation.', 5),
  ('DECI_L45.S3.C3', 'DECI_L45.S3', 'DECI_L45', false, 3, 'Data science insight', 'Collected project data is organized/visualized to produce a useful insight that supports a real user or business decision.', 5),
  ('DECI_L45.S3.C4', 'DECI_L45.S3', 'DECI_L45', false, 4, 'Integration of AI/data into system behavior', 'AI/data results trigger meaningful dashboard updates, alerts, predictions, recommendations, or other actions in the same solution.', 5),
  ('DECI_L45.S4.C1', 'DECI_L45.S4', 'DECI_L45', false, 1, 'Product identity & professional visualization', 'Brand/UI is consistent and polished; mixed Level 4-5 team includes strong product visuals/digital assets appropriate to Level 5 depth.', 5),
  ('DECI_L45.S4.C2', 'DECI_L45.S4', 'DECI_L45', false, 2, 'Web application integration', 'Web/app interface exposes the correct live/history/control information from the hardware/AI system and supports the intended user flow.', 5),
  ('DECI_L45.S4.C3', 'DECI_L45.S4', 'DECI_L45', false, 3, 'Cybersecurity design', 'Authentication/authorization, access control, communication/data protection, and relevant risks are addressed in a way that fits the architecture.', 5),
  ('DECI_L45.S5.C1', 'DECI_L45.S5', 'DECI_L45', false, 1, 'Business model & product planning', 'Customer, value proposition, pricing, competitors/alternatives, and delivery approach are complete and realistic.', 5),
  ('DECI_L45.S5.C2', 'DECI_L45.S5', 'DECI_L45', false, 2, 'Testing evidence & measurable success criteria', 'Team tests under relevant conditions and shows evidence such as logs, accuracy results, repeated runs, failure cases, or comparison to ground truth.', 5),
  ('DECI_L45.S5.C3', 'DECI_L45.S5', 'DECI_L45', false, 3, 'Iteration, reliability & improvement', 'Test results lead to concrete improvements; team can explain limitations, reliability concerns, and next technical/product steps.', 5),
  ('DECI_L45.S6.C1', 'DECI_L45.S6', 'DECI_L45', false, 1, 'Cross-discipline teamwork & ownership', 'Hardware, software, AI/data, design, security, and business work are integrated; members have visible contributions and shared ownership.', 5),
  ('DECI_L45.S6.C2', 'DECI_L45.S6', 'DECI_L45', false, 2, 'Technical communication & decision justification', 'Team explains architecture and tradeoffs clearly and can justify why technologies/components were chosen.', 5),
  ('DECI_L45.S6.C3', 'DECI_L45.S6', 'DECI_L45', false, 3, 'Presentation, live demo & Q&A', 'Presentation is polished and concise, demo evidence is convincing, and multiple members answer judge questions confidently.', 5),
  ('DECI_L45.BONUS.C1', 'DECI_L45.BONUS', 'DECI_L45', true, 1, 'Advanced AI/ML feature', 'Optional advanced AI feature goes beyond the core AI/data pipeline and is supported by evidence or a credible prototype.', 5),
  ('DECI_L45.BONUS.C2', 'DECI_L45.BONUS', 'DECI_L45', true, 2, 'Advanced IoT / security feature', 'Optional advanced cloud, real-time communication, automation, monitoring, or security capability strengthens the same architecture.', 5),
  ('DECI_L45.BONUS.C3', 'DECI_L45.BONUS', 'DECI_L45', true, 3, 'Level 5 advanced security / reliability', 'Optional Level-5-depth feature such as stronger authentication, secure protocols, monitoring, risk management, or reliability safeguards is demonstrated with evidence.', 5)
